tsconfig.json.text:
{
  "$schema": "https://json.schemastore.org/tsconfig",

  // Cloudflare Workers tsconfig. For a Workers project, use THIS file INSTEAD of
  // the base TypeScript overlay's tsconfig.json (same relationship the Astro overlay
  // has). It carries every strict flag from the base overlay, plus Workers specifics.
  "compilerOptions": {
    // --- Target and module ---
    "target": "ES2022",
    "module": "esnext",
    "moduleResolution": "bundler",
    "lib": ["ES2022"],

    // --- Workers-specific ---
    // wrangler bundles the Worker (esbuild under the hood), so tsc never emits.
    // Type-check only; let wrangler build.
    "noEmit": true,
    // Generated by `wrangler types` (npm run cf-typegen). Provides the typed Env
    // (your bindings) AND the workerd runtime types keyed to compatibility_date.
    // Prefer this over manually depending on @cloudflare/workers-types — it cannot
    // drift from wrangler.jsonc the way a hand-pinned types package can.
    "types": ["./worker-configuration.d.ts", "@cloudflare/vitest-plugin/types"],

    // --- strict: true enables strictNullChecks, strictFunctionTypes,
    // strictBindCallApply, strictPropertyInitialization, noImplicitAny,
    // noImplicitThis, useUnknownInCatchVariables, alwaysStrict ---
    "strict": true,

    // --- Additional flags NOT in strict: true (carried from the base overlay) ---
    // arr[i] is T | undefined — forces handling the miss. Critical at trust boundaries.
    "noUncheckedIndexedAccess": true,
    // Absent property != property set to undefined. Kills silent auth/financial defaults.
    "exactOptionalPropertyTypes": true,
    // Make overrides explicit to readers and the compiler.
    "noImplicitOverride": true,

    // --- Additional safety flags ---
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "noFallthroughCasesInSwitch": true,
    "forceConsistentCasingInFileNames": true,

    // --- Interop ---
    "esModuleInterop": true,
    "isolatedModules": true,
    "resolveJsonModule": true,

    "skipLibCheck": true
  },

  "include": ["src/**/*", "worker-configuration.d.ts"],
  "exclude": ["node_modules", "dist", "build"]
}

src/index.ts.text:
export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    if (request.method !== "POST") return new Response("method", { status: 405 });
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return new Response("invalid JSON", { status: 400 });
    }
    if (
      typeof body !== "object" ||
      body === null ||
      !("value" in body) ||
      typeof body.value !== "string" ||
      body.value.length === 0
    )
      return new Response("invalid value", { status: 400 });
    try {
      await env.KV.put("message", body.value);
    } catch {
      return new Response("storage unavailable", { status: 503 });
    }
    return new Response("stored", { status: 201 });
  },
} satisfies ExportedHandler<Env>;

src/index.test.ts.text:
import { env, exports } from "cloudflare:workers";
import { expect, it } from "vitest";
import worker from "./index";

it("actual workerd binding and integration effect", async () => {
  const response = await exports.default.fetch("https://example.com/", {
    method: "POST",
    body: JSON.stringify({ value: "hello" }),
  });
  expect(response.status).toBe(201);
  expect(await env.KV.get("message")).toBe("hello");
});
it("invalid shape preserves prior state", async () => {
  await env.KV.put("message", "prior");
  const response = await exports.default.fetch("https://example.com/", {
    method: "POST",
    body: JSON.stringify({ value: 42 }),
  });
  expect(response.status).toBe(400);
  expect(await env.KV.get("message")).toBe("prior");
});
it("malformed JSON preserves state", async () => {
  await env.KV.put("message", "prior");
  const response = await exports.default.fetch("https://example.com/", {
    method: "POST",
    body: "{",
  });
  expect(response.status).toBe(400);
  expect(await env.KV.get("message")).toBe("prior");
});
it("method rejects before state changes", async () => {
  await env.KV.put("message", "prior");
  const response = await exports.default.fetch("https://example.com/");
  expect(response.status).toBe(405);
  expect(await env.KV.get("message")).toBe("prior");
});
it("effect failure is explicit, not success", async () => {
  const badEnv = {
    ...env,
    KV: {
      ...env.KV,
      put: async () => {
        throw new Error("fixture storage failure");
      },
    },
  };
  const response = await worker.fetch(
    new Request("https://example.com/", {
      method: "POST",
      body: JSON.stringify({ value: "hello" }),
    }),
    badEnv,
  );
  expect(response.status).toBe(503);
  expect(await response.text()).toBe("storage unavailable");
});
